"use node";
import {action} from "./_generated/server";
import {createHash} from "node:crypto";
export const health=action({args:{},handler:async(ctx)=>{const i=await ctx.auth.getUserIdentity();if(!i||i.issuer!=="https://unrelated-task06-custom.example")throw Error("HOST_AUTH_REQUIRED");return {runtime:"node",hash:createHash("sha256").update("unrelated-host-node").digest("hex"),subject:i.subject};}});
